//! Cargo-driven `arp.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is arp-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_mainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "mainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "mainCRTStartup"),
        o => panic!("arp-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:oldnames"],
        "x86_64" => &["engine:oldnames"],
        "aarch64" => &["engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("arp-rust")
        .c_from_compile_db("arp_shims", &["base/applications/network/arp/rust_varargs_shim.c"])
        .resource_from_rc("base/applications/network/arp/arp.rc", "arp_res")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
